open(p,'a').write('''
/** Batch read that keeps the order of `issueIds`; unknown ids are skipped. */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const db = getDb();
  const rows = [];
  for (let at = 0; at < issueIds.length; at += IN_CHUNK) {
    rows.push(
      ...db
        .select()
        .from(issues)
        .where(
          and(
            orgPredicate(issues.orgId, orgId),
            inArray(issues.id, issueIds.slice(at, at + IN_CHUNK)),
          ),
        )
        .all(),
    );
  }

  const labelRows = [];
  for (let at = 0; at < issueIds.length; at += IN_CHUNK) {
    labelRows.push(
      ...db
        .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            inArray(issueLabels.issueId, issueIds.slice(at, at + IN_CHUNK)),
          ),
        )
        .all(),
    );
  }

  const labelsByIssue = new Map<string, LabelId[]>();
  for (const row of labelRows) {
    const bucket = labelsByIssue.get(row.issueId) ?? [];
    bucket.push(brandId<LabelId>(row.labelId));
    labelsByIssue.set(row.issueId, bucket);
  }

  const byId = new Map(rows.map((row) => [row.id, row]));
  return issueIds.flatMap((id) => {
    const row = byId.get(id);
    return row ? [toIssue(row, labelsByIssue.get(id) ?? [])] : [];
  });
}

/** Keeps `IN (...)` lists well under SQLite's bound-variable ceiling. */
const IN_CHUNK = 400;

/** The persisted record of one completed bulk import. */
export type IssueImportRecord = {
  importKey: string;
  projectId: ProjectId;
  issueIds: readonly IssueId[];
};

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

/** One row of a bulk import, already resolved to an assignee id. */
export type ImportedIssueDraft = {
  title: string;
  description: string | null;
  status: IssueStatus;
  priority: IssuePriority;
  assigneeId: UserId | null;
  dueAt: IsoTimestamp | null;
  /** Label names; matched exactly against the org's labels, created if new. */
  labelNames: readonly string[];
};

/**
 * Writes a whole import in one transaction: missing labels, the issues
 * (numbered in draft order after the project's highest number), their label
 * links and the import record. Returns `null` without writing anything when
 * the org has already imported `importKey`.
 */
export async function insertIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  drafts: readonly ImportedIssueDraft[];
}): Promise<readonly Issue[] | null> {
  const { orgId, projectId, importKey, authorId, drafts } = input;
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const existing = tx
      .select({ id: issueImports.id })
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, orgId),
          eq(issueImports.importKey, importKey),
        ),
      )
      .get();
    if (existing) return null;

    const labelIdByName = new Map<string, LabelId>();
    const wanted = new Set(drafts.flatMap((draft) => draft.labelNames));
    if (wanted.size > 0) {
      const known = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, orgId))
        .all();
      for (const label of known) {
        labelIdByName.set(label.name, brandId<LabelId>(label.id));
      }
      for (const name of wanted) {
        if (labelIdByName.has(name)) continue;
        const id = newId();
        tx.insert(labels)
          .values({
            id,
            orgId,
            name,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, brandId<LabelId>(id));
      }
    }

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
      )
      .get();
    let nextNumber = (highest?.value ?? 0) + 1;

    const created: Issue[] = [];
    for (const draft of drafts) {
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: nextNumber,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
      nextNumber += 1;

      const labelIds = [...new Set(draft.labelNames)].flatMap((name) => {
        const id = labelIdByName.get(name);
        return id === undefined ? [] : [id];
      });
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({ orgId, issueId: row.id, labelId })),
          )
          .run();
      }

      created.push(toIssue(row, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey,
        projectId,
        importedBy: authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
      })
      .run();

    return created;
  });
}
''')

