/**
 * Email → user id for the org's current active members, keyed by the
 * lower-cased address. Removed (archived), invited and suspended members are
 * left out, as is everyone who belongs only to another org.
 */
export async function mapActiveMemberEmails(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();

  return new Map(
    rows.map((row) => [row.email.toLowerCase(), brandId<UserId>(row.userId)]),
  );
}
