const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Bulk import: every row becomes an issue in the project, in file order, or
 * nothing is written at all. Gates run in this order — tenant scope, a live
 * project, `issue:create`, the replay lookup, the per-project quota for the
 * whole batch, then the org's issue-creation rate allowance (one unit per
 * row). A key the org has already imported returns that first result and
 * spends nothing. One `issues.imported` event announces the batch; no
 * per-issue `issue.created` is published.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const earlier = await issueRepo.findIssueImport(input.orgId, input.importKey);
  if (earlier) return replayImport(actor, project.id, earlier);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const memberByEmail = await memberRepo.mapActiveMemberEmails(input.orgId);

  const created = await issueRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    authorId: actor.userId,
    drafts: input.rows.map((row) => ({
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId:
        row.assigneeEmail == null
          ? null
          : (memberByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt ?? null,
      labelNames: row.labels ?? [],
    })),
  });

  if (created === null) {
    // Lost a race with the same key: the other upload is the first import.
    const winner = requireFound(
      await issueRepo.findIssueImport(input.orgId, input.importKey),
      "Issue import",
      input.importKey,
    );
    return replayImport(actor, project.id, winner);
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: created.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues: created,
    replayed: false,
  };
}

/**
 * Answers a re-uploaded key with the first import's issues. When that import
 * went into a different project than the one now named, the actor must be
 * allowed to create issues there too before its issues are handed back.
 */
async function replayImport(
  actor: Actor,
  requestedProjectId: ProjectId,
  earlier: issueRepo.IssueImportRecord,
): Promise<IssueImportResult> {
  if (earlier.projectId !== requestedProjectId) {
    const original = requireFound(
      await projectRepo.findProjectById(actor.orgId, earlier.projectId),
      "Project",
      earlier.projectId,
    );
    assertCan(actor, "issue:create", projectResource(original));
  }

  return {
    importKey: earlier.importKey,
    projectId: earlier.projectId,
    issues: await issueRepo.findIssuesByIds(actor.orgId, earlier.issueIds),
    replayed: true,
  };
}

